// Value category examples:

// LVALUE - has identity, can take address
int x = 10;              // x is lvalue
int* p = &x;             // OK: lvalue has address
int& ref = x;            // OK: bind lvalue ref to lvalue

// PRVALUE - temporary, no identity
int y = 42;              // 42 is prvalue
int* p2 = &42;           // ERROR: prvalue has no address
const int& cref = 42;    // OK: const lvalue ref extends lifetime

// XVALUE - expiring value, can be moved from
std::string s = "hello";
std::string&& rref = std::move(s);  // std::move(s) is xvalue

// GLVALUE (lvalue or xvalue) - has identity
std::string& lval_ref = s;           // s is glvalue (lvalue)
std::string&& xval_ref = std::move(s); // std::move(s) is glvalue (xvalue)

// Function return types determine category:
int  func1();     // Call is prvalue
int& func2();     // Call is lvalue
int&& func3();    // Call is xvalue

code_example:
#include <iostream>
#include <string>
#include <utility>  // for std::move
#include <type_traits>

// Helper to show value categories at compile time
template<typename T>
void show_category(T&&) {
    std::cout << "Type: " << typeid(T).name() << "\n";
    if (std::is_lvalue_reference<T>::value)
        std::cout << "  Category: lvalue\n";
    else if (std::is_rvalue_reference<T>::value)
        std::cout << "  Category: rvalue (xvalue or prvalue)\n";
    else
        std::cout << "  Category: prvalue\n";
}

class Widget {
public:
    Widget() { std::cout << "Widget()\n"; }
    Widget(const Widget&) { std::cout << "Widget(const Widget&) - copy\n"; }
    Widget(Widget&&) noexcept { std::cout << "Widget(Widget&&) - move\n"; }
};

// Functions with different return types
Widget func_by_value() { return Widget(); }       // Returns prvalue
Widget& func_by_lvalue_ref(Widget& w) { return w; } // Returns lvalue
Widget&& func_by_rvalue_ref(Widget&& w) { return std::move(w); } // Returns xvalue

int main() {
    std::cout << "=== Value Categories Demo ===\n\n";

    // 1. LVALUE examples
    std::cout << "--- Lvalues ---\n";
    Widget w1;
    Widget& lref = w1;              // w1 is lvalue
    Widget* ptr = &w1;              // Can take address of lvalue
    std::cout << "Address of lvalue w1: " << ptr << "\n\n";

    // 2. PRVALUE examples
    std::cout << "--- Prvalues ---\n";
    // Widget(); is prvalue (temporary)
    // int* bad = &Widget();         // ERROR: cannot take address of prvalue
    const Widget& cref = Widget();   // OK: lifetime extended
    int literal = 42;                // 42 is prvalue
    std::cout << "Prvalue literal: " << literal << "\n\n";

    // 3. XVALUE examples
    std::cout << "--- Xvalues ---\n";
    Widget w2;
    Widget&& rref = std::move(w2);   // std::move(w2) is xvalue
    // std::move(w2) has identity but is expiring (can be moved from)
    std::cout << "xvalue bound to rvalue reference\n\n";

    // 4. Function return categories
    std::cout << "--- Function Return Categories ---\n";
    Widget w3;

    std::cout << "func_by_value() -> prvalue:\n";
    Widget w4 = func_by_value();     // prvalue: may elide copy

    std::cout << "\nfunc_by_lvalue_ref() -> lvalue:\n";
    Widget& lv = func_by_lvalue_ref(w3);

    std::cout << "\nfunc_by_rvalue_ref() -> xvalue:\n";
    Widget w5 = func_by_rvalue_ref(std::move(w3)); // xvalue: triggers move

    // 5. Assignment yields lvalue
    std::cout << "\n--- Assignment Yields Lvalue ---\n";
    int a, b, c;
    (a = b = c = 5);  // Assignment is right-associative, yields lvalue
    std::cout << "Chained assignment: a=" << a << ", b=" << b << ", c=" << c << "\n";

    // 6. Glvalue-to-prvalue conversion (lvalue-to-rvalue conversion)
    std::cout << "\n--- Glvalue to Prvalue Conversion ---\n";
    int x = 10;       // x is lvalue
    int y = x;        // x converted to prvalue (reads the value)
    std::cout << "x (lvalue) converted to prvalue for assignment: y=" << y << "\n";

    return 0;
}

// Output:
// === Value Categories Demo ===
//
// --- Lvalues ---
// Widget()
// Address of lvalue w1: 0x...
//
// --- Prvalues ---
// Widget()
// Prvalue literal: 42
//
// --- Xvalues ---
// Widget()
// xvalue bound to rvalue reference
//
// --- Function Return Categories ---
// func_by_value() -> prvalue:
// Widget()
// Widget(Widget&&) - move       <- prvalue enables move/elision
//
// func_by_lvalue_ref() -> lvalue:
//
// func_by_rvalue_ref() -> xvalue:
// Widget(Widget&&) - move       <- xvalue triggers move constructor
//
// --- Assignment Yields Lvalue ---
// Chained assignment: a=5, b=5, c=5
//
// --- Glvalue to Prvalue Conversion ---
// x (lvalue) converted to prvalue for assignment: y=10
